                av_log(c->fc, AV_LOG_ERROR, "Invalid stsc index.\n");

                return AVERROR_INVALIDDATA;

            }

        }

    }



    sc->stsc_count = i;



    if (pb->eof_reached)

        return AVERROR_EOF;



    return 0;

}


